using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class PRCheck {
 static string O=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_PropRefinement/");
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var bad=new List<string>();
 foreach(var t in ts){if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)bad.Add("Missing script "+t.name);foreach(var f in t.GetComponents<MeshFilter>())if(!f.sharedMesh)bad.Add("Missing mesh "+t.name);foreach(var r in t.GetComponents<Renderer>())if(r.sharedMaterials.Any(m=>!m||!m.shader))bad.Add("Missing material "+t.name);}
 var items=JArray.Parse(File.ReadAllText(O+"applied.json"));var models=new List<object>();foreach(var item in items){var t=ts.Single(x=>x.name==(string)item["target"]);var lod=t.GetComponent<LODGroup>();var levels=lod.GetLODs();if(levels.Length!=3||levels.Any(l=>l.renderers.Length!=1||!l.renderers[0].name.StartsWith("PR_")))bad.Add("LOD "+t.name);foreach(string p in item["oldRenderersDisabled"].Values<string>()){var rr=ts.Single(x=>AnimationUtility.CalculateTransformPath(x,null)==p).GetComponent<Renderer>();if(rr.enabled)bad.Add("Old renderer enabled "+p);}models.Add(new{t.name,levels=levels.Select(l=>new{threshold=l.screenRelativeTransitionHeight,mesh=l.renderers[0].GetComponent<MeshFilter>().sharedMesh.name}).ToArray()});}
 var shader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Afrer_Seconds/05.Model/Props/1F/PRPropLit.shader");var messages=ShaderUtil.GetShaderMessages(shader);if(ShaderUtil.ShaderHasError(shader))bad.Add("Prop shader error");object[] counts={0,0,0};typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("GetCountsByType",BindingFlags.Public|BindingFlags.Static).Invoke(null,counts);
 var result=new{scene=s.path,saved=!s.isDirty,transforms=ts.Length,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),missingOrInvalid=bad,shaderMessages=messages.Select(m=>new{m.message,m.severity,m.file,m.line}).ToArray(),consoleErrors=counts[0],consoleWarnings=counts[1],models};File.WriteAllText(O+"check.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{result.transforms,result.colliders,result.missingOrInvalid,result.consoleErrors,result.consoleWarnings,shaderMessages=messages.Length};}
}
